const {test}=require('node:test');
const assert=require('node:assert/strict');
const vm=require('node:vm');const fs=require('node:fs');const path=require('node:path');
function boot(seed={}){const data={...seed},elements={};const context=vm.createContext({console,Blob,URL,setTimeout,localStorage:{getItem:k=>data[k]||null,setItem:(k,v)=>data[k]=v},document:{getElementById:id=>elements[id]||(elements[id]={innerHTML:'',value:'',textContent:'',hidden:false,setAttribute(k,v){this[k]=v},scrollIntoView(){}}),querySelectorAll:()=>[]}});for(const f of ['common-content.js','curriculum.js','biology.js','biology-cards.js','biology-practice.js','biology-extended-practice.js','biology-core-gaps.js','biology-diagrams.js','biology-question-bank.js','maths.js','trilogy-content.js','science-courses.js','learning-tools.js','exam-resources.js','spec-audit-data.js','spec-audit.js','biology-reuse.js','biology-cell-completion.js','biology-transport-completion.js','biology-digestion-completion.js','biology-circulation-completion.js','biology-plant-completion.js','biology-infection-completion.js','biology-medicines-completion.js','biology-bioenergetics-completion.js','biology-coordination-completion.js','biology-reproduction-completion.js','biology-inheritance-completion.js','biology-evolution-completion.js','biology-ecology-field-completion.js','biology-ecology-impact-completion.js','foundation-tier-data.js','foundation-tier.js','mcq-option-order-data.js','mcq-option-order.js','app.js','coverage.js'])vm.runInContext(fs.readFileSync(path.join(__dirname,'..',f),'utf8'),context);return {run:code=>vm.runInContext(code,context),data,elements};}
test('migrates Build 4 to common core once and preserves original data',()=>{const original=JSON.stringify({mastery:{'Biology|Cell Biology':72,'History|Medicine Through Time':40},attempts:8,correct:5,examBoard:'AQA'}),b=boot({gcseStudyHub_staging_706L_V3:original});assert.equal(b.run("choice('Biology').board"),'aqa');b.run("changeChoice('Biology','board','common')");assert.equal(b.run("mastery('Biology','Cell Biology')"),72);b.run("changeChoice('Biology','board','aqa')");assert.equal(b.run("mastery('Biology','Cell Biology')"),0);assert.equal(b.data.gcseStudyHub_staging_706L_V3,original);const again=boot(b.data);assert.equal(again.run("choice('Biology').board"),'aqa');assert.equal(again.run("state.legacySummary.mastery['History|Medicine Through Time']"),40);});
test('board and tier records stay separate and switching back restores mastery',()=>{const b=boot();b.run("startQuiz('Biology','Cell Biology');answerOption(session?.queue[session.index]?.options?.indexOf(session.queue[session.index].answer)??0);answerOption(session?.queue[session.index]?.options?.indexOf(session.queue[session.index].answer)??0)");assert.equal(b.run("record('Biology').attempts"),1);assert.equal(b.run("mastery('Biology','Cell Biology')"),12);b.run("changeChoice('Biology','board','edexcel');changeChoice('Biology','tier','higher')");assert.equal(b.run("mastery('Biology','Cell Biology')"),0);b.run("changeChoice('Biology','board','aqa');changeChoice('Biology','tier','higher')");assert.equal(b.run("mastery('Biology','Cell Biology')"),12);assert.equal(b.run("choice('Maths').board"),'aqa');});
test('mistakes only include failed questions in selected pathway; retry clears them',()=>{const b=boot();b.run("startQuiz('Biology','Cell Biology');answerOption((session.queue[session.index].options.indexOf(session.queue[session.index].answer)+1)%4);quizMode='mistakes';startQuiz('Biology','Cell Biology')");assert.equal(b.run('session.queue.length'),1);b.run('answerOption(session?.queue[session.index]?.options?.indexOf(session.queue[session.index].answer)??0)');assert.equal(b.run("Object.keys(record('Biology').mistakes).length"),0);b.run("startQuiz('Biology','Cell Biology')");assert.equal(b.run('session.queue.length'),0);});
test('empty topic never falls back to unrelated questions',()=>{const b=boot();b.run("startQuiz('English Literature','Poetry')");assert.equal(b.run('session.queue.length'),0);assert.match(b.elements.app.innerHTML,/No practice questions/);});
test('tier filter excludes Higher content until confirmed',()=>{const b=boot();for(const tier of ['foundation','unsure'])assert.equal(b.run(`resolveQuestions('Maths','aqa','${tier}').some(q=>q.id==='aqa-maths-completing-square')`),false);assert.equal(b.run("resolveQuestions('Maths','aqa','higher').some(q=>q.id==='aqa-maths-completing-square')"),true);assert.equal(b.run("Boolean(PACKS.French.ocr)"),false);});
test('all question topics exist in their pack and all registered packs resolve',()=>{const b=boot();assert.equal(b.run("Object.entries(PACKS).every(([s,bs])=>Object.entries(bs).every(([b,p])=>resolveQuestions(s,b,'higher').every(q=>p.topics.some(t=>t.id===q.topic))))"),true);assert.notEqual(b.run("JSON.stringify(resolveTopics('Biology','aqa'))"),b.run("JSON.stringify(resolveTopics('Biology','edexcel'))"));});
test('short answers use full matches and cannot score twice',()=>{const b=boot();b.run("startQuiz('Maths','Algebra')");b.elements.ans={value:'8'};b.run('shortAnswer();shortAnswer()');assert.equal(b.run("record('Maths').correct"),0);assert.equal(b.run("record('Maths').attempts"),1);});
test('written responses require explicit self assessment',()=>{const b=boot();b.run("startQuiz('English Language','Language Analysis')");b.elements.ans={value:'A sentence'};b.run('shortAnswer()');assert.equal(b.run("record('English Language').attempts"),0);b.run('selfAssess(true);selfAssess(true)');assert.equal(b.run("record('English Language').attempts"),1);});
test('module test attempts are scoped and do not inflate mastery',()=>{const b=boot();b.run("changeChoice('Biology','board','edexcel');startTest('Biology','Cell Biology')");b.elements.t0={value:'attempt'};b.run('submitTest();submitTest()');assert.equal(b.run("mastery('Biology','Cell Biology')"),0);assert.equal(b.run("record('Biology').tests['Cell Biology'].answered"),1);b.run("changeChoice('Biology','board','common')");assert.equal(b.run("record('Biology').tests['Cell Biology']"),undefined);});
test('5/8/12 sessions are bounded and adaptive length responds to mastery',()=>{const b=boot();for(const length of [5,8,12]){b.run(`quizLength=${length};startQuiz()`);assert.equal(b.run('session.queue.length'),Math.min(length,b.run('questionPool().length')));}b.run("quizLength='auto';startQuiz()");assert.equal(b.run('session.requested'),5);b.run("for(const q of questionPool())record(q.subject).mastery[q.topic]=80;startQuiz()");assert.equal(b.run('session.requested'),12);});
test('corrupt stored JSON recovers without deleting legacy data',()=>{const b=boot({gcseStudyHub_staging_706L_V3:'{broken'});assert.equal(b.run('state.version'),5);assert.equal(b.data.gcseStudyHub_staging_706L_V3,'{broken');assert.match(b.run('storageWarning'),/could not be read/);});
test('invalid V5 data is retained for recovery instead of crashing',()=>{const bad=JSON.stringify({version:5,choices:{},records:{bad:{}}});const b=boot({gcseStudyHub_staging_706L_V5:bad});assert.equal(b.data['gcseStudyHub_staging_706L_V5-recovery'],bad);assert.equal(b.run('state.version'),5);});
test('valid backups restore saved scores; invalid backups leave state unchanged',async()=>{const b=boot();b.run("startQuiz('Biology','Cell Biology');answerOption(session?.queue[session.index]?.options?.indexOf(session.queue[session.index].answer)??0)");const before=b.data.gcseStudyHub_staging_706L_V5;await b.run(`importProgress({text:async()=>${JSON.stringify(before)}})`);assert.equal(b.run("mastery('Biology','Cell Biology')"),12);await b.run("importProgress({text:async()=>'{\"version\":5,\"choices\":{},\"records\":{\"bad\":{}}}'})");assert.equal(b.run("mastery('Biology','Cell Biology')"),12);assert.match(b.elements['import-result'].textContent,/not a valid/);});
test('navigation cancels active sessions so later clicks cannot affect a new pathway',()=>{const b=boot();b.run("startQuiz('Biology','Cell Biology');setPage('settings');changeChoice('Biology','board','aqa');answerOption(session?.queue[session.index]?.options?.indexOf(session.queue[session.index].answer)??0)");assert.equal(b.run("record('Biology').attempts"),0);});
test('every Biology module has substantive lessons, questions and module tests',()=>{const b=boot();assert.equal(b.run("Object.keys(PACKS.Biology).every(board=>PACKS.Biology[board].topics.every(t=>{const l=resolveLesson('Biology',board,t.id,'foundation');return l.sections.length>=4&&l.sections.every(s=>s.body.length>100)&&resolveQuestions('Biology',board,'foundation').filter(q=>q.topic===t.id).length>=3;}))"),true);});
test('Higher Biology sections and questions are excluded below Higher',()=>{const b=boot();for(const tier of ['foundation','unsure']){assert.equal(b.run(`resolveLesson('Biology','aqa','Homeostasis & Response','${tier}').sections.some(s=>s.title==='Hormonal feedback')`),false);assert.equal(b.run(`resolveQuestions('Biology','aqa','${tier}').some(q=>q.id==='bio2-feedback')`),false);}assert.equal(b.run("resolveLesson('Biology','aqa','Homeostasis & Response','higher').sections.some(s=>s.title==='Hormonal feedback')"),true);});
test('Biology question IDs are unique and existing question IDs survive',()=>{const b=boot();assert.equal(b.run("Object.keys(PACKS.Biology).every(board=>{const qs=resolveQuestions('Biology',board,'higher');return qs.length===new Set(qs.map(q=>q.id)).size&&qs.some(q=>q.id==='build4-0');})"),true);});
test('Edexcel enzymes and cell control practice follow Edexcel topic organisation',()=>{const b=boot();assert.equal(b.run("resolveQuestions('Biology','edexcel','foundation').find(q=>q.id==='bio2-denature').topic"),'Cell Biology');assert.equal(b.run("resolveQuestions('Biology','edexcel','foundation').find(q=>q.id==='bio2-mitosis').topic"),'Cells and Control');assert.equal(b.run("resolveQuestions('Biology','edexcel','foundation').find(q=>q.id==='bio2-selection').topic"),'Natural Selection');});
test('AQA practical set and Edexcel core practical set are distinct',()=>{const b=boot();assert.equal(b.run("PACKS.Biology.aqa.topics.flatMap(t=>resolveLesson('Biology','aqa',t.id,'foundation').practicals).length"),10);assert.equal(b.run("PACKS.Biology.edexcel.topics.flatMap(t=>resolveLesson('Biology','edexcel',t.id,'foundation').practicals).length"),8);});

test('fresh courses start on AQA and the all-AQA action preserves other progress',()=>{const b=boot();assert.equal(b.run("Object.keys(SUBJECTS).every(s=>choice(s).board==='aqa')"),true);b.run("changeChoice('Biology','board','edexcel');record('Biology').mastery['Cell Biology']=44;setAllAqa()");assert.equal(b.run("choice('Biology').board"),'aqa');b.run("changeChoice('Biology','board','edexcel')");assert.equal(b.run("mastery('Biology','Cell Biology')"),44);});
test('AQA Maths has visual lessons, topic practice, and Higher filtering',()=>{const b=boot();assert.equal(b.run("PACKS.Maths.aqa.topics.every(t=>resolveLesson('Maths','aqa',t.id,'foundation').sections.length>=3&&resolveQuestions('Maths','aqa','foundation').filter(q=>q.topic===t.id).length>=4&&mathsVisual(t.id).includes('<svg'))"),true);assert.equal(b.run("resolveQuestions('Maths','aqa','foundation').some(q=>q.id==='aqa-maths-surd')"),false);assert.equal(b.run("resolveQuestions('Maths','aqa','higher').some(q=>q.id==='aqa-maths-surd')"),true);});
test('correct-answer feedback is warm and explains the answer',()=>{const b=boot();b.run("startQuiz('Biology','Cell Biology');answerOption(session?.queue[session.index]?.options?.indexOf(session.queue[session.index].answer)??0)");assert.match(b.elements.feedback.innerHTML,/Yes! You got it/);assert.match(b.elements.feedback.innerHTML,/nucleus/i);});
test('AQA tier boundaries retain Foundation maths and add Higher topics',()=>{const b=boot();assert.equal(b.run("resolveQuestions('Maths','aqa','foundation').some(q=>q.id==='aqa-maths-trig'&&q.tier==='both')"),true);assert.equal(b.run("resolveQuestions('Maths','aqa','foundation').some(q=>q.id==='aqa-quadratic')"),true);for(const id of ['aqa-maths-completing-square','aqa-maths-sine-rule','aqa-maths-conditional','aqa-maths-frequency-density','aqa-maths-midpoint-proof'])assert.equal(b.run("resolveQuestions('Maths','aqa','foundation').some(q=>q.id==="+JSON.stringify(id)+")"),false);});
test('AQA Maths question IDs are unique across the selected tier',()=>{const b=boot();for(const tier of ['unsure','foundation','higher'])assert.equal(b.run("(()=>{const q=resolveQuestions('Maths','aqa',"+JSON.stringify(tier)+");return q.length===new Set(q.map(x=>x.id)).size})()"),true);});
test('quick lessons lead with three short points and hide long reading',()=>{const b=boot();b.run("openLesson('Maths','Number')");const html=b.elements.app.innerHTML;assert.match(html,/THE QUICK VERSION/);assert.match(html,/Fractions are pieces/);assert.match(html,/maths-visual/);assert.match(html,/<details class=\"card lesson-deeper\">/);assert.match(html,/Play video/);b.run("openLesson('Biology','Cell Biology')");assert.match(b.elements.app.innerHTML,/tiny building blocks/);});
test('video loads only after a valid play click',()=>{const b=boot();b.run("openLesson('Maths','Number')");assert.doesNotMatch(b.elements.app.innerHTML,/<iframe/);b.run("playLessonVideo('lalcQLW6MWE')");assert.match(b.elements['lesson-video'].innerHTML,/youtube-nocookie/);b.run("closeLessonVideo()");assert.equal(b.elements['lesson-video'].innerHTML,'');b.run("playLessonVideo('invalid')");assert.equal(b.elements['lesson-video'].innerHTML,'');});
test('AQA Maths has a broad practice bank and three worked examples per module',()=>{const b=boot();assert.equal(b.run("PACKS.Maths.aqa.topics.every(t=>resolveQuestions('Maths','aqa','foundation').filter(q=>q.topic===t.id).length>=12&&MATHS_WORKED[t.id].length===3)"),true);assert.equal(b.run("resolveQuestions('Maths','aqa','higher').length")>100,true);});
test('a topic session prioritises questions not used in the last session',()=>{const b=boot();assert.equal(b.run("(()=>{quizLength=5;startQuiz('Maths','Number');const first=session.queue.map(q=>q.id);for(let i=0;i<first.length;i++){grade(false);quizNext();}startQuiz('Maths','Number');return session.queue.every(q=>!first.includes(q.id));})()"),true);assert.equal(b.run("Object.keys(record('Maths').seen).length"),5);});
test('revision cards reveal on request and Higher cards follow the tier',()=>{const b=boot();b.run("openLesson('Maths','Number')");assert.match(b.elements.app.innerHTML,/revision-cards/);assert.match(b.elements.app.innerHTML,/HIGHER CHALLENGE/);b.run("document.getElementById('revision-cards').hidden=true;toggleRevisionCards()");assert.equal(b.elements['revision-cards'].hidden,false);b.run('toggleRevisionCards()');assert.equal(b.elements['revision-cards'].hidden,true);b.run("changeChoice('Maths','tier','foundation');openLesson('Maths','Number')");assert.doesNotMatch(b.elements.app.innerHTML,/HIGHER CHALLENGE/);b.run("openLesson('Biology','Cell Biology')");assert.match(b.elements.app.innerHTML,/KEY WORDS/);});
test('module tests stay short as practice banks grow',()=>{const b=boot();assert.equal(b.run("testItems('Maths','Algebra').length<=10"),true);assert.equal(b.run("testItems('Maths','Number').length<=6"),true);});
test('every AQA Biology lesson subsection has its own labelled visual card',()=>{const b=boot();const summary=b.run("PACKS.Biology.aqa.topics.map(t=>{const sections=resolveLesson('Biology','aqa',t.id,'higher').sections;const cards=biologyCards(t.id,sections);return {topic:t.id,sections:sections.length,cards:cards.length,complete:cards.every((c,i)=>c.front===sections[i].title&&c.back&&c.visualHtml.includes('aria-label')&&c.keywords.length&&c.tip)}})");for(const row of summary){assert.equal(row.cards,row.sections,row.topic);assert.equal(row.complete,true,row.topic);}assert.equal(summary.reduce((sum,row)=>sum+row.cards,0),67);});
test('AQA Biology cards follow tier selection and appear with visuals in the lesson',()=>{const b=boot();const higher=b.run("biologyCards('Cell Biology',resolveLesson('Biology','aqa','Cell Biology','higher').sections)");const foundation=b.run("biologyCards('Cell Biology',resolveLesson('Biology','aqa','Cell Biology','foundation').sections)");assert.equal(higher.length,foundation.length+1);b.run("openLesson('Biology','Cell Biology')");assert.match(b.elements.app.innerHTML,/bio-cell-outline/);assert.match(b.elements.app.innerHTML,/One card for each lesson step/);b.run("changeChoice('Biology','tier','foundation');openLesson('Biology','Cell Biology')");assert.match(b.elements.app.innerHTML,/Surface-area-to-volume reasoning/);});
test('AQA Cell Biology has at least eight subsection questions and a worked example per step',()=>{const b=boot();assert.equal(b.run("CELL_PRACTICE.length"),16);assert.equal(b.run("Object.keys(CELL_WORKED).length"),8);assert.equal(b.run("resolveQuestions('Biology','aqa','higher').filter(q=>q.id.startsWith('aqa-cell-')).length"),16);assert.equal(b.run("resolveQuestions('Biology','aqa','foundation').filter(q=>q.id.startsWith('aqa-cell-')).length"),14);assert.equal(b.run("resolveQuestions('Biology','edexcel','higher').some(q=>q.id.startsWith('aqa-cell-'))"),false);assert.equal(b.run("resolveLesson('Biology','aqa','Cell Biology','higher').sections.every(s=>CELL_WORKED[s.title]&&resolveQuestions('Biology','aqa','higher').filter(q=>q.topic==='Cell Biology'&&q.section===s.title).length>=8)"),true);b.run("openLesson('Biology','Cell Biology')");assert.match(b.elements.app.innerHTML,/TRY EACH STEP/);assert.match(b.elements.app.innerHTML,/Try 5 questions/);b.run("startSectionPractice('Cell Biology','Inside a cell')");assert.equal(b.run('session.queue.length'),5);assert.match(b.elements.app.innerHTML,/cell-question-svg/);});
test('Biology label diagrams support placement, checking and reset',()=>{const b=boot();assert.equal(b.run("Object.values(BIO_DIAGRAMS).flat().length"),12);b.run("openLesson('Biology','Cell Biology')");assert.match(b.elements.app.innerHTML,/Label an animal cell/);assert.match(b.elements.app.innerHTML,/dragstart/);assert.match(b.elements.app.innerHTML,/tap a label/);b.run("for(let i=0;i<4;i++){selectBioLabel('animal-cell',BIO_DIAGRAMS['Cell Biology'][0].labels[i]);placeBioLabel('animal-cell',i)}");assert.equal(b.run("checkBioDiagram('animal-cell')"),4);b.run("resetBioDiagram('animal-cell')");assert.equal(b.run("Object.keys(bioDiagramPlacements['animal-cell']||{}).length"),0);b.run("openLesson('Biology','Ecology')");assert.match(b.elements.app.innerHTML,/Label a food chain/);});
test('tricky Biology cards persist by board and tier without changing mastery',()=>{const b=boot();b.run("openLesson('Biology','Cell Biology');markBioCard('Cell Biology','Inside a cell',true,0)");assert.equal(b.run("record('Biology').cardReviews['Cell Biology|Inside a cell'].needsReview"),true);assert.equal(b.run("mastery('Biology','Cell Biology')"),0);b.run("showBioCards('tricky')");assert.match(b.elements.app.innerHTML,/Tricky cards \(1\)/);assert.doesNotMatch(b.elements.app.innerHTML,/CARD 2/);b.run("changeChoice('Biology','tier','foundation')");assert.equal(b.run("record('Biology').cardReviews['Cell Biology|Inside a cell']"),undefined);b.run("changeChoice('Biology','tier','higher')");assert.equal(b.run("record('Biology').cardReviews['Cell Biology|Inside a cell'].needsReview"),true);const again=boot(b.data);assert.equal(again.run("record('Biology').cardReviews['Cell Biology|Inside a cell'].needsReview"),true);});
test('all 67 AQA Biology subsections have one worked example and at least eight matching questions',()=>{const b=boot();const rows=b.run("PACKS.Biology.aqa.topics.map(t=>{const ss=resolveLesson('Biology','aqa',t.id,'higher').sections;const qs=resolveQuestions('Biology','aqa','higher');return {topic:t.id,count:ss.length,complete:ss.every(s=>BIOLOGY_WORKED[t.id]?.[s.title]?.steps.length>=2&&qs.filter(q=>q.topic===t.id&&q.section===s.title).length>=8)}})");assert.equal(rows.reduce((n,r)=>n+r.count,0),67);for(const row of rows)assert.equal(row.complete,true,row.topic);assert.equal(b.run("resolveQuestions('Biology','aqa','higher').filter(q=>q.section).length"),536);assert.equal(b.run("resolveQuestions('Biology','aqa','foundation').filter(q=>q.section&&q.tier==='higher').length"),0);});
test('new Biology answers vary position and subsection practice returns to its lesson',()=>{const b=boot();const positions=b.run("[...new Set(resolveQuestions('Biology','aqa','higher').filter(q=>q.id.startsWith('aqa-bio-step-')).map(q=>q.options.indexOf(q.answer)))]");assert.equal(positions.length,4);b.run("openLesson('Biology','Organisation')");assert.match(b.elements.app.innerHTML,/One small idea at a time/);assert.match(b.elements.app.innerHTML,/Try 5 questions/);b.run("startSectionPractice('Organisation','Enzymes and digestion')");assert.equal(b.run('session.queue.length'),5);b.run('for(let i=0;i<5;i++){grade(true);quizNext()}');assert.match(b.elements.app.innerHTML,/Back to lesson/);});
test('shared AQA Biology additions have cards, examples, mixed questions and no other-board leakage',()=>{const b=boot();assert.equal(b.run('BIO_SHARED_GAPS.length'),7);for(const gap of b.run('BIO_SHARED_GAPS.map(g=>({topic:g.topic,title:g.title}))')){const q=b.run(`resolveQuestions('Biology','aqa','foundation').filter(q=>q.topic===${JSON.stringify(gap.topic)}&&q.section===${JSON.stringify(gap.title)})`);assert.equal(q.length,8,gap.title);assert.equal(q.some(x=>x.type==='writing'),true,gap.title);assert.equal(b.run(`Boolean(BIOLOGY_CARD_DATA[${JSON.stringify(gap.topic)}][${JSON.stringify(gap.title)}])`),true,gap.title);assert.equal(b.run(`Boolean(BIOLOGY_WORKED[${JSON.stringify(gap.topic)}][${JSON.stringify(gap.title)}])`),true,gap.title);assert.equal(b.run(`resolveQuestions('Biology','edexcel','higher').some(q=>q.section===${JSON.stringify(gap.title)})`),false,gap.title);}b.run("changeScienceCourse('unsure');openLesson('Biology','Organisation')");assert.match(b.elements.app.innerHTML,/Science course still to confirm/);assert.match(b.elements.app.innerHTML,/Label a leaf cross-section/);});
test('existing AQA Biology saved progress survives added shared-core steps',()=>{const b=boot();b.run("record('Biology').mastery['Organisation']=64;record('Biology').cardReviews['Organisation|The heart and blood']={needsReview:true,reviewedAt:1};save()");const next=boot(b.data);assert.equal(next.run("mastery('Biology','Organisation')"),64);assert.equal(next.run("record('Biology').cardReviews['Organisation|The heart and blood'].needsReview"),true);assert.equal(next.run("resolveLesson('Biology','aqa','Organisation','unsure').sections.some(s=>s.title==='Leaf tissues and their jobs')"),true);});
test('science course choice persists and keeps mastery separate across views',()=>{const b=boot();b.run("changeScienceCourse('unsure');record('Biology').mastery['Cell Biology']=30;changeScienceCourse('trilogy')");assert.equal(b.run("mastery('Biology','Cell Biology')"),0);b.run("record('Biology').mastery['Cell Biology']=61;changeScienceCourse('synergy')");assert.equal(b.run("mastery('Biology','Cell Biology')"),0);b.run("changeScienceCourse('trilogy')");assert.equal(b.run("mastery('Biology','Cell Biology')"),61);b.run("changeScienceCourse('unsure')");assert.equal(b.run("mastery('Biology','Cell Biology')"),30);assert.equal(boot(b.data).run('scienceCourse()'),'unsure');});
test('Trilogy and Synergy show distinct paper guides',()=>{const b=boot();b.run("changeScienceCourse('trilogy');setPage('science')");assert.equal(b.run('SCIENCE_PAPERS.trilogy.length'),6);assert.match(b.elements.app.innerHTML,/Biology Paper 2/);b.run("changeScienceCourse('synergy')");assert.equal(b.run('SCIENCE_PAPERS.synergy.length'),4);assert.match(b.elements.app.innerHTML,/Paper 4/);assert.doesNotMatch(b.elements.app.innerHTML,/Biology Paper 2/);});
