test('older Build 5 saves load with an unconfirmed science course',()=>{const b=boot();b.run('save()');const x=JSON.parse(b.data.gcseStudyHub_staging_706L_V5);delete x.scienceCourse;const loaded=boot({gcseStudyHub_staging_706L_V5:JSON.stringify(x)});assert.equal(loaded.run('scienceCourse()'),'unsure');});
