test('wrong answers show a short Quick Fix instead of the full lesson',()=>{const b=boot();b.run("startQuiz('Biology','Cell Biology');answerOption((session.queue[session.index].options.indexOf(session.queue[session.index].answer)+1)%4)");const html=b.elements.feedback.innerHTML;assert.match(html,/QUICK FIX · 30 SECONDS/);assert.match(html,/Answer/);assert.match(html,/Why/);assert.match(html,/Exam tip/);assert.doesNotMatch(html,/Revisit the lesson/);assert.doesNotMatch(html,/<details>/);assert.equal(html.length<1800,true);});
test('Quick Fix offers an immediate retry of the same question',()=>{const b=boot();b.run("startQuiz('Biology','Cell Biology')");const id=b.run('session.queue[0].id');b.run("answerOption((session.queue[session.index].options.indexOf(session.queue[session.index].answer)+1)%4);retryQuestion()");assert.equal(b.run('session.queue[session.index].id'),id);assert.equal(b.run('session.answered'),false);assert.match(b.elements.app.innerHTML,/Question 1/);});
