test('wrong-answer Quick Fix includes a concise Grade 8/9 upgrade',()=>{const b=boot();b.run("startQuiz('Biology','Cell Biology');answerOption((session.queue[session.index].options.indexOf(session.queue[session.index].answer)+1)%4)");const html=b.elements.feedback.innerHTML;assert.match(html,/Grade 8\/9/);assert.match(html,/Example:/);assert.match(html,/correct because/);assert.doesNotMatch(html,/Link structure|apply that chain/);assert.equal(html.length<2300,true);});
