test('revision lessons and cards enforce audited tier eligibility',()=>{const b=boot();b.run("openLesson('Biology','Bioenergetics')");assert.match(b.elements.app.innerHTML,/Interacting limiting factors/);for(const tier of ['foundation','unsure']){b.run(`changeChoice('Biology','tier','${tier}')`);assert.doesNotMatch(b.elements.app.innerHTML,/Interacting limiting factors/);}b.run("changeChoice('Biology','tier','higher')");assert.match(b.elements.app.innerHTML,/Interacting limiting factors/);});
test('topic tier metadata is respected without changing pack order or progress',()=>{const b=boot();b.run("PACKS.Maths.aqa.topics[1].tier='higher';record('Maths').mastery[PACKS.Maths.aqa.topics[1].id]=61;changeChoice('Maths','tier','foundation')");assert.equal(b.run("activeTopics('Maths').some(t=>t.id===PACKS.Maths.aqa.topics[1].id)"),false);assert.equal(b.run("activeLesson('Maths',choice('Maths'),PACKS.Maths.aqa.topics[1].id)"),null);b.run("changeChoice('Maths','tier','higher')");assert.equal(b.run("activeTopics('Maths')[1].id"),b.run("PACKS.Maths.aqa.topics[1].id"));assert.equal(b.run("mastery('Maths',PACKS.Maths.aqa.topics[1].id)"),61);});
test('switching board inside a lesson clears old feedback and returns unavailable topics to the library',()=>{const b=boot();b.run("changeChoice('Biology','board','edexcel');openLesson('Biology','Cells and Control');state.lessonFocus={subject:'Biology',topic:'Cells and Control',answer:'old pathway answer'};changeChoice('Biology','board','ocr')");assert.equal(b.run('state.page'),'subjects');assert.equal(b.run('state.lessonFocus'),null);assert.doesNotMatch(b.elements.app.innerHTML,/old pathway answer/);assert.equal(b.run("activeLesson('Biology',choice('Biology'),'Cells and Control')"),null);});
test('science course topic lists and preview labels follow the saved course',()=>{const b=boot();b.run("changeScienceCourse('separate');openLesson('Physics','Space Physics')");assert.equal(b.run('state.page'),'lesson');b.run("changeScienceCourse('trilogy')");assert.equal(b.run('state.page'),'subjects');assert.equal(b.run("activeTopics('Physics').some(t=>t.id==='Space Physics')"),false);assert.deepEqual(b.run("activeTopics('Chemistry').map(t=>t.id)"),b.run("TRILOGY_TOPICS.Chemistry.map(t=>t[1])"));b.run("changeScienceCourse('synergy')");assert.equal(b.run("activeTopics('Biology').every(t=>t.unit.includes('preview'))"),true);assert.match(b.elements.app.innerHTML,/Full theme mapping is not yet available/);b.run("changeChoice('Biology','board','common')");assert.equal(b.run("activeTopics('Biology').every(t=>t.unit==='Shared material')"),true);});
test('revision pathway progress survives board tier and course round trips and reload',()=>{const b=boot();for(const board of ['aqa','edexcel','ocr','common'])for(const tier of ['higher','foundation','unsure'])for(const course of board==='aqa'?['trilogy','separate','synergy','unsure']:['trilogy'])b.run(`changeChoice('Biology','board','${board}');changeChoice('Biology','tier','${tier}');changeScienceCourse('${course}');record('Biology').mastery['Cell Biology']=${10+['aqa','edexcel','ocr','common'].indexOf(board)*20+['higher','foundation','unsure'].indexOf(tier)*5+['trilogy','separate','synergy','unsure'].indexOf(course)};save()`);const next=boot(b.data);for(const board of ['aqa','edexcel','ocr','common'])for(const tier of ['higher','foundation','unsure'])for(const course of board==='aqa'?['trilogy','separate','synergy','unsure']:['trilogy']){next.run(`changeChoice('Biology','board','${board}');changeChoice('Biology','tier','${tier}');changeScienceCourse('${course}');openLesson('Biology','Cell Biology')`);assert.equal(next.run("mastery('Biology','Cell Biology')"),10+['aqa','edexcel','ocr','common'].indexOf(board)*20+['higher','foundation','unsure'].indexOf(tier)*5+['trilogy','separate','synergy','unsure'].indexOf(course));}});

test('admin report leaves live student selections and saved progress unchanged',()=>{const b=boot();b.run("changeScienceCourse('synergy');changeChoice('Biology','board','edexcel');record('Biology').mastery['Cell Biology']=74;save()");const before=b.run('JSON.stringify(state)'),saved=JSON.stringify(b.data);b.run('coverageReport()');assert.equal(b.run('JSON.stringify(state)'),before);assert.equal(JSON.stringify(b.data),saved);});

test('specification audit preserves saved student choices and progress',()=>{const b=boot();b.run("changeChoice('Biology','board','ocr');changeScienceCourse('synergy');record('Biology').mastery['Cell Biology']=63;save()");const before=b.run('JSON.stringify(state)'),stored=JSON.stringify(b.data);b.run('specificationAudit()');assert.equal(b.run('JSON.stringify(state)'),before);assert.equal(JSON.stringify(b.data),stored);});
